const SVG_NS = 'http://www.w3.org/2000/svg';

/** 用模板元素解析出一份全新的 <svg>（新元素 = 动画重新计时）。 */
function freshSvg() {
  const tpl = document.createElement('template');
  tpl.innerHTML = BSC_SVG.trim();
  return /** @type {SVGElement} */ (tpl.content.firstElementChild);
}

function resolveHost(host) {
  if (!host) return null;
  return typeof host === 'string' ? document.querySelector(host) : host;
}

/**
 * 重播 BSC 动画：把 .dsc-bsc 里的 <svg> 整块换成新解析的实例。
 * 新 DOM 节点上的 CSS 动画会从 0 重新计时，比切换 class 更可靠
 * （不需要 void offsetWidth 之类的强制回流 hack）。
 *
 * @param {Element|string} host  .dsc-bsc 容器（也接受 <svg> 本身或 CSS 选择器）
 * @returns {SVGElement|null}    新的 <svg>，找不到宿主时返回 null
 */
export function replayBsc(host) {
  if (typeof document === 'undefined') return null;
  const el = resolveHost(host);
  if (!el || el.nodeType !== 1) return null;
  const isSvg = el.namespaceURI === SVG_NS && el.tagName.toLowerCase() === 'svg';
  const old = isSvg ? el : el.querySelector('svg');
  const next = freshSvg();
  if (old && old.parentNode) {
    old.replaceWith(next);
    return next;
  }
  if (!isSvg) {
    el.appendChild(next);
    return next;
  }
  return null;
}
